const nightMode = node({"type":"n8n-nodes-base.set","version":3.5,"config":{"name":"Nightly generation mode","parameters":{"mode":"raw","jsonOutput":"{\"dry_run\": false, \"timezone\": \"America/Toronto\", \"max_batches\": 120, \"send_notification\": false, \"build_only\": true}","includeOtherFields":false}},"output":[{"action":0,"ok":true}]});
const morningMode = node({"type":"n8n-nodes-base.set","version":3.5,"config":{"name":"Select saved morning report","parameters":{"mode":"raw","jsonOutput":expr("{{ {intent: \"notify_only\", local_date: $now.setZone(\"America/Toronto\").toISODate()} }}"),"includeOtherFields":false}},"output":[{"action":0,"ok":true}]});
