const runBatch = node({"type":"n8n-nodes-base.executeWorkflow","version":1.4,"config":{"name":"Run report batch","parameters":{"source":"database","workflowId":{"__rl":true,"mode":"id","value":expr("{{ $workflow.id }}")},"workflowInputs":{"mappingMode":"defineBelow","value":{"intent":expr("{{ $json.cfg.build_only ? 'build_batch' : ($json.phase === 'send' ? 'manual_send' : 'manual_batch') }}"),"local_date":expr("{{ $json.local_date }}")},"schema":[{"id":"intent","displayName":"intent","type":"string","required":true,"display":true},{"id":"local_date","displayName":"local_date","type":"string","required":true,"display":true}]},"mode":"once","options":{"waitForSubWorkflow":true}},"retryOnFail":false},"output":[{"status":"complete","errors":[],"classification_saved":3,"classification_deferred":0}]});
const batchAdvance = node({"type":"n8n-nodes-base.code","version":2,"config":{"name":"Advance classification batches","parameters":{"mode":"runOnceForAllItems","jsCode":"'use strict';\n\nfunction newBatchPlan(cfg, now) {\n  if(!cfg.report_workflow_id || !Number.isInteger(cfg.max_batches) || cfg.max_batches<1 || cfg.max_batches>1000)throw new Error('invalid_batch_configuration');\n  return {cfg,local_date:now.setZone(cfg.timezone).toISODate(),phase:'classify',action:0,batches:0,previous_deferred:null,total_classified:0,result:null};\n}\n\nfunction manualBatchPlan(cfg, workflowId, now) {\n  return newBatchPlan({...cfg,report_workflow_id:workflowId,send_notification:cfg.dry_run!==true && cfg.send_notification!==false},now);\n}\n\nfunction advanceBatches(state, result, now) {\n  if(now.setZone(state.cfg.timezone).toISODate()!==state.local_date)throw new Error('manual_run_crossed_midnight');\n  if(result.status!=='complete' || result.errors?.length)throw new Error('report_batch_incomplete');\n  const deferred=result.classification_deferred;\n  const saved=result.classification_saved;\n  if(!Number.isInteger(deferred) || deferred<0 || !Number.isInteger(saved) || saved<0)throw new Error('invalid_batch_result');\n  state.batches+=1;\n  state.total_classified+=saved;\n  state.result=result;\n  if(deferred>0) {\n    if(state.previous_deferred!==null && deferred>=state.previous_deferred && saved===0)throw new Error('classification_batch_no_progress');\n    state.previous_deferred=deferred;\n    state.phase='classify';\n  } else if(state.phase==='classify') {\n    if(state.cfg.send_notification===false){state.action=1;return state;}\n    state.phase='send';\n  } else {\n    state.action=1;\n    return state;\n  }\n  if(state.batches>=state.cfg.max_batches)throw new Error('classification_batch_limit');\n  return state;\n}\n\nreturn [{json:advanceBatches($('Dispatch batches').item.json,$input.first().json,$now)}];"}},"output":[{"action":1,"phase":"send"}]});
const finalSummary = node({"type":"n8n-nodes-base.code","version":2,"config":{"name":"Manual run result","parameters":{"mode":"runOnceForAllItems","jsCode":"const s=$input.first().json;return [{json:{...s.result,processing_batches:s.batches,total_classified:s.total_classified}}];"}},"output":[{"status":"complete","delivery_state":"accepted"}]});
const note = sticky('## Manual run and dry run\nExecute workflow processes yesterday through successive small batches, then calls Home Assistant. Run mode: dry_run=false sends a real notification; dry_run=true processes without sending or destructive cleanup. All logic is in this workflow; batch executions call its own batch entry. Daily generation runs at 00:30 without notifying. At 08:00 only the saved, fully generated report is sent. Sunday selects the weekly report. Manual run still processes and notifies; delivery fencing prevents duplicates. Schedules require publication.');
export default workflow('pet-reporting-morning','Pet Journal · Morning reports')
.add(manual).to(runMode).to(batchPlan).to(batchDispatch)
.add(nightSchedule).to(nightMode).to(runMode)
.add(schedule).to(morningMode).to(settingsNode)
.add(batchDispatch.onCase(0,runBatch.to(batchAdvance).to(batchDispatch)).onCase(1,finalSummary))
.add(subworkflow).to(settingsNode).to(initializeNode).to(dispatch)
.add(dispatch.onCase(0,write.to(advanceNode)).onCase(1,read.to(advanceNode)).onCase(2,login.to(advanceNode)).onCase(3,source.to(advanceNode)).onCase(4,group.to(dispatch)).onCase(5,image.to(vision).to(validateModel).to(dispatch)).onCase(6,notify.to(advanceNode)).onCase(7,complete))
.add(advanceNode).to(dispatch)
.add(note)
.group('Run and notify',[runMode,batchPlan,batchDispatch,runBatch,batchAdvance,finalSummary],{description:'Processes every eligible visit through small executions of this same workflow, then sends a notification unless Run mode has dry_run=true.'})
.group('Process one batch',[settingsNode,initializeNode,dispatch,write,read,login,source,advanceNode,group,image,vision,validateModel,notify,complete],{description:'Collects yesterday, caches evidence, classifies a bounded batch, saves reports and guards Home Assistant delivery.'});
